19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
23	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	  rune: 25,
31	  moonstone: 25,
32	};
33	
34	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
35	
36	/** The policy base premium is the sum of the base premiums of its items. */
37	const policyBasePremium = (items: Item[]): number =>
38	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
39	
40	const quotePremium = (step: QuoteStep): number => {
41	  const premiumAfterFirstInsuranceSurcharge =
42	    policyBasePremium(step.items) * (1 + FIRST_INSURANCE_SURCHARGE);
43	
44	  return roundUp(premiumAfterFirstInsuranceSurcharge + PROCESSING_FEE);
45	};
46	
47	export const runScenario = (scenario: Scenario): ScenarioResults => ({
48	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
49	});
